import {esc} from '../config.mjs';
export function contentMarkup(settings,p){const date=p.next_live_at?new Date(p.next_live_at).toLocaleString('sv-SE',{timeZone:'America/Sao_Paulo'}).slice(0,16).replace(' ','T'):'';return `<section><h1>Conteúdo e LIVE</h1><p>O que você salvar aqui será usado pelo app do cliente. As filas e os pagamentos existentes permanecem registrados.</p><form class="paper" data-content-form><h2>Banner de destaque</h2><label for="content-episode-title">Título do banner</label><input id="content-episode-title" name="episodeTitle" maxlength="120" value="${esc(settings.featured_episode_title||'')}"><label for="content-episode-url">Link para assistir</label><input id="content-episode-url" name="episodeUrl" type="url" maxlength="500" value="${esc(settings.featured_episode_url||'')}" placeholder="https://www.youtube.com/watch?v=…"><p class="hint">O banner fica disponível por até 3 dias após a publicação no Controle; depois disso o app deixa de exibi-lo automaticamente até que um novo banner seja salvo.</p><h2>Programação da LIVE</h2><label for="content-live-title">Título da próxima LIVE</label><input id="content-live-title" name="liveTitle" maxlength="120" value="${esc(p.next_live_title||'')}"><label for="content-live-url">Link para assistir à LIVE</label><input id="content-live-url" name="liveUrl" type="url" maxlength="500" value="${esc(p.next_live_url||'')}" placeholder="Link HTTPS do YouTube ou TikTok"><label for="content-live-date">Data e horário de Brasília · opcional</label><input id="content-live-date" name="liveAt" type="datetime-local" value="${esc(date)}"><label for="content-topic">Assunto em conversa</label><textarea id="content-topic" name="topic" maxlength="180">${esc(p.topic||'')}</textarea><label class="check"><input name="accepting" type="checkbox" ${p.live_accepting?'checked':''}><span>Aceitar novas mensagens para a LIVE</span></label><p class="hint">Sem limite de vagas. Sem data, o app informa “Próxima LIVE · data a confirmar”. O link é para assistir; abrir ou fechar a fila é uma decisão separada.</p><button class="btn" type="submit">Salvar conteúdo e programação</button><p class="error" role="alert" data-content-error></p><p role="status" data-content-status></p></form><div class="actions"><a class="btn secondary" href="/#assistir" target="_blank" rel="noopener">Ver destaque no app</a><a class="btn secondary" href="/#live" target="_blank" rel="noopener">Ver área da LIVE</a><button class="btn secondary" data-control-route="management">Voltar à Gestão</button></div></section>`}
export function mountContent(host,call,settings){let disposed=false;host.innerHTML='<div class="empty">Carregando conteúdo e programação…</div>';(async()=>{try{const d=await call('admin.programming',{});if(disposed)return;host.innerHTML=contentMarkup(settings,d.programming||{});host.querySelector('[data-content-form]').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button'),f=new FormData(e.target);button.disabled=true;host.querySelector('[data-content-error]').textContent='';try{await call('admin.content.update',{payload:{episodeTitle:f.get('episodeTitle'),episodeUrl:f.get('episodeUrl'),topic:f.get('topic'),liveTitle:f.get('liveTitle'),liveUrl:f.get('liveUrl'),liveAt:f.get('liveAt')?new Date(f.get('liveAt')+':00-03:00').toISOString():'',accepting:f.has('accepting'),capacity:50}});if(!disposed){delete e.target.dataset.unsaved;host.querySelector('[data-content-status]').textContent='Banner, link da LIVE e programação salvos no app.'}}catch(error){if(!disposed)host.querySelector('[data-content-error]').textContent=error.message}finally{if(!disposed)button.disabled=false}}}catch(e){if(!disposed)host.innerHTML='<div class="empty">'+esc(e.message)+'</div>'}})();return()=>{disposed=true;host.replaceChildren()}}
